private static final void prepareMap(Context context) {
    MapLibre.getInstance(context.getApplicationContext());
    if (mapHttpInstalled) {
        return;
    }
    HttpRequestUtil.setLogEnabled(false);
    HttpRequestUtil.setPrintRequestUrlOnFailure(false);
    HttpRequestUtil.setOkHttpClient(new OkHttpClient.Builder().cache(new Cache(new File(context.getCacheDir(), "map-http"), 50331648L)).connectTimeout(15L, TimeUnit.SECONDS).readTimeout(20L, TimeUnit.SECONDS).addInterceptor(new Interceptor() { // from class: dev.kiankonrad.weather.MapsKt$prepareMap$$inlined$-addInterceptor$1
        @Override // okhttp3.Interceptor
        public final Response intercept(Interceptor.Chain chain) {
            Intrinsics.checkNotNullParameter(chain, "chain");
            return chain.proceed(chain.request().newBuilder().header("User-Agent", "Weather/1.1.1 (https://github.com/Kian-hdr/Weather; dev.kiankonrad.weather)").build());
        }
    }).build());
    mapHttpInstalled = true;
}
